INSERT INTO `faqs` (`uuid`, `pertanyaan`, `kategori`, `jawaban`, `urutan`, `status`, `created_at`, `updated_at`) VALUES ('108c2d82-314f-4a88-9fc7-00dcb10e9dcf','Apakah konsultasi dengan Sagita Wedding Planner dikenakan biaya?','Pemesanan & Pembayaran','Untuk informasi mengenai biaya konsultasi, silakan hubungi tim kami melalui WhatsApp. Tim kami akan menjelaskan ketentuan konsultasi sesuai dengan jenis dan kebutuhan layanan yang ingin Anda diskusikan.',3,'active','2026-11-23 02:53:49','2026-11-23 02:53:49'),
('119a640c-5a9f-49c5-81dc-16863d9bdb6e','Apakah saya bisa memesan layanan jauh-jauh hari sebelum tanggal pernikahan?','Pemesanan & Pembayaran','Tentu. Anda dapat menghubungi kami jauh-jauh hari untuk memeriksa ketersediaan tanggal dan mendiskusikan kebutuhan pernikahan. Pemesanan tetap bergantung pada ketersediaan tim dan proses konfirmasi dari Sagita Wedding Planner.',2,'active','2026-11-23 02:53:19','2026-11-23 02:53:19'),
('3913d51c-30f6-4baf-9e42-0422ee84149d','Apakah saya bisa menambahkan layanan di luar paket yang dipilih?','Paket & Layanan','Bisa. Jika terdapat kebutuhan tambahan di luar fasilitas paket, Anda dapat menyampaikannya kepada tim kami. Kami akan memeriksa ketersediaan layanan dan memberikan informasi mengenai biaya tambahannya sebelum disepakati.',4,'active','2026-11-23 02:49:24','2026-11-23 02:49:24'),
('3c2c017d-5470-4b38-a1b8-922d95caaa16','Apakah paket pernikahan dapat disesuaikan dengan budget saya?','Paket & Layanan','Kami memahami bahwa setiap pasangan memiliki kebutuhan dan anggaran yang berbeda. Anda dapat menyampaikan anggaran yang telah disiapkan saat konsultasi agar tim kami dapat membantu memberikan pilihan layanan yang paling sesuai. Penyesuaian layanan akan dibahas berdasarkan kebutuhan dan kesepakatan bersama.',3,'active','2026-11-23 02:49:02','2026-11-23 02:49:02'),
('4370a810-eab9-43da-8ce0-cb0791e3b319','Apakah tanggal atau jumlah tamu pernikahan dapat diubah setelah pemesanan?','Perubahan & Pembatalan','Perubahan tanggal maupun jumlah tamu dapat diajukan kepada tim kami untuk dibahas lebih lanjut. Perubahan tanggal dapat dilakukan satu kali tanpa biaya perubahan jadwal apabila diajukan paling lambat H-60 sebelum tanggal acara semula, dengan tetap mempertimbangkan ketersediaan tim dan vendor. Perubahan jumlah tamu akan disesuaikan dengan kebutuhan layanan dan kemungkinan adanya biaya tambahan.',1,'active','2026-11-23 02:59:38','2026-11-23 02:59:38'),
('4b9411a3-ccc5-44fd-bc24-e8dc7065773c','Kapan sebaiknya saya mulai menggunakan jasa Wedding Organizer?','Perencanaan Pernikahan','Sebaiknya persiapan dimulai sejak Anda sudah memiliki gambaran tanggal atau konsep pernikahan. Dengan persiapan lebih awal, tim kami dapat membantu menyusun rencana, mengatur kebutuhan acara, dan mengoordinasikan berbagai hal agar persiapan berjalan lebih terarah.',1,'active','2026-11-20 02:25:31','2026-11-23 02:45:59'),
('5a914d46-c3e0-4eb7-bcfb-3807a4ffc63e','Apakah Sagita Wedding Planner membantu mengoordinasikan seluruh vendor pada hari pernikahan?','Vendor & Mitra','Tim kami membantu mengoordinasikan vendor yang termasuk dalam ruang lingkup layanan yang telah disepakati. Koordinasi dilakukan agar setiap pihak memahami tugas dan waktu pelaksanaan sesuai rundown acara. Tanggung jawab masing-masing vendor tetap mengikuti kesepakatan antara pelanggan dan vendor tersebut.',3,'active','2026-11-23 02:57:23','2026-11-23 02:57:23'),
('6bb623f8-916a-436b-85b3-a57035fe5ac5','Apakah saya harus sudah memiliki konsep pernikahan sebelum menghubungi Sagita Wedding Planner?','Perencanaan Pernikahan','Tidak harus. Jika Anda masih belum menentukan konsep pernikahan, Anda tetap dapat berkonsultasi dengan kami. Tim Sagita Wedding Planner akan membantu mendiskusikan pilihan konsep berdasarkan kebutuhan, preferensi, dan anggaran yang Anda miliki.',4,'active','2026-11-20 02:25:31','2026-11-23 02:47:37'),
('6d93f634-aff6-4031-a675-be73a42f95cd','Bagaimana jika saya ingin membatalkan pemesanan?','Perubahan & Pembatalan','Pembatalan dapat diajukan dengan menghubungi tim Sagita Wedding Planner melalui saluran komunikasi resmi. DP yang telah dibayarkan tidak dapat dikembalikan. Untuk pembayaran selain DP, penyelesaiannya akan mengikuti ketentuan kontrak dengan mempertimbangkan pekerjaan dan biaya yang telah dikeluarkan.',2,'active','2026-11-23 03:00:07','2026-11-23 03:00:07'),
('7488cc60-0408-401a-a4c2-b5f429a52a88','Kapan pemesanan saya dinyatakan resmi atau terkonfirmasi?','Pemesanan & Pembayaran','Pemesanan dinyatakan terkonfirmasi setelah tanggal acara dan ketersediaan tim disetujui, rincian layanan serta biaya disepakati, kontrak ditandatangani, dan pembayaran DP diterima serta diverifikasi oleh tim kami. Mengisi formulir atau memilih paket melalui website belum berarti tanggal pernikahan telah diamankan.',5,'active','2026-11-23 02:55:22','2026-11-23 02:55:22'),
('805fb184-af2c-41b1-b1a7-5843c5988106','Apa saja yang dilakukan tim Wedding Organizer pada hari pernikahan?','Pelaksanaan Acara','Pada hari pernikahan, tim kami bertugas membantu mengoordinasikan jalannya acara berdasarkan rundown yang telah disepakati. Hal ini mencakup koordinasi dengan vendor, pengaturan alur acara, serta membantu memastikan setiap rangkaian kegiatan berjalan sesuai rencana dan ruang lingkup layanan.',1,'active','2026-11-23 02:58:07','2026-11-23 02:58:07'),
('9118b31c-bbee-48bb-a199-69e252b575c3','Bagaimana jika terjadi kendala atau perubahan saat acara berlangsung?','Pelaksanaan Acara','Tim kami akan membantu menangani kendala teknis dan melakukan koordinasi dengan pihak terkait sesuai kondisi di lapangan. Setiap penyesuaian akan diupayakan agar tidak mengganggu rangkaian acara lainnya dan tetap memperhatikan kesepakatan layanan.',3,'active','2026-11-23 02:58:53','2026-11-23 02:58:53'),
('93509b35-53a5-49ae-8606-2db63ca3ebdb','Bagaimana sistem pembayaran layanan Sagita Wedding Planner?','Pemesanan & Pembayaran','Pembayaran dilakukan secara bertahap sesuai kesepakatan dalam kontrak. Pembayaran pertama berupa DP sebesar 30% saat penandatanganan kontrak, pembayaran kedua sebesar 40% paling lambat H-90, dan pelunasan sebesar 30% paling lambat H-30 sebelum acara.',4,'active','2026-11-23 02:54:39','2026-11-23 02:54:39'),
('95b200f1-69c7-4f1b-a76b-172bcf5fcc55','Apa perbedaan antara paket Wedding Organizer yang tersedia?','Paket & Layanan','Setiap paket memiliki fasilitas dan cakupan layanan yang berbeda, mulai dari jenis pendampingan persiapan hingga kebutuhan koordinasi pada hari pernikahan. Anda dapat melihat rincian masing-masing paket pada halaman Paket & Layanan atau menghubungi tim kami untuk mendapatkan penjelasan lebih lanjut.',2,'active','2026-11-20 02:25:31','2026-11-23 02:48:31'),
('9f25d34e-2a60-42cf-8379-ed069dc50ac0','Apakah Sagita Wedding Planner dapat membantu pernikahan dengan konsep atau adat tertentu?','Perencanaan Pernikahan','Ya. Kami dapat membantu mempersiapkan pernikahan dengan berbagai konsep, baik modern, tradisional, maupun konsep khusus sesuai keinginan Anda. Detail kebutuhan akan dibicarakan terlebih dahulu agar persiapan dan koordinasi acara dapat disesuaikan.',3,'active','2026-11-20 02:25:31','2026-11-23 02:47:15'),
('ada50e41-ab47-4b2a-84a9-cf81356afdf7','Apakah Sagita Wedding Planner akan membuat rundown acara?','Pelaksanaan Acara','Ya. Tim kami akan membantu menyusun rundown berdasarkan konsep, susunan acara, dan kebutuhan pernikahan yang telah dibahas bersama Anda. Rundown tersebut akan menjadi panduan bagi tim Wedding Organizer dan pihak terkait selama acara berlangsung.',2,'active','2026-11-23 02:58:32','2026-11-23 02:58:32'),
('af82cc7f-1eb9-474d-8b41-33231075ba5d','Apakah keluarga pengantin perlu ikut mengurus jalannya acara jika sudah menggunakan jasa Wedding Organizer?','Pelaksanaan Acara','Keluarga tetap dapat menikmati acara tanpa harus terlibat langsung dalam seluruh urusan teknis. Tim Sagita Wedding Planner akan membantu koordinasi sesuai tugas yang telah disepakati, sehingga keluarga dapat lebih fokus mendampingi pengantin dan menyambut tamu undangan.',4,'active','2026-11-23 02:59:15','2026-11-23 02:59:15'),
('b32eed85-6e25-41a3-bae0-ac3ca63de2d6','Bagaimana cara melakukan pemesanan layanan Sagita Wedding Planner?','Pemesanan & Pembayaran','Pemesanan dapat dimulai dengan menghubungi tim kami melalui WhatsApp dan menyampaikan informasi mengenai tanggal, lokasi, serta kebutuhan pernikahan Anda. Selanjutnya, tim kami akan membantu proses konsultasi, memberikan informasi paket dan biaya, serta menjelaskan tahapan pemesanan. Setelah terdapat kesepakatan mengenai layanan dan biaya, proses dilanjutkan dengan penandatanganan kontrak dan pembayaran DP sesuai ketentuan. Pemesanan dinyatakan terkonfirmasi setelah seluruh persyaratan tersebut dipenuhi dan pembayaran DP telah diverifikasi.',1,'active','2026-11-23 02:52:57','2026-11-23 02:52:57'),
('c9483e9c-22f4-4ed6-8bda-a218359ee574','Apakah saya boleh menggunakan vendor pilihan sendiri?','Vendor & Mitra','Tentu. Anda tetap dapat menggunakan vendor pilihan sendiri sesuai kebutuhan pernikahan. Namun, vendor tersebut perlu dikoordinasikan bersama tim Sagita Wedding Planner agar pembagian tugas, kebutuhan teknis, dan susunan acara dapat disesuaikan dengan rencana pernikahan.',1,'active','2026-11-23 02:56:31','2026-11-23 02:56:31'),
('f371dc29-2cb9-474a-8dbc-677dec663a02','Apakah Sagita Wedding Planner menyediakan rekomendasi vendor?','Vendor & Mitra','Ya. Kami dapat membantu memberikan rekomendasi vendor sesuai kebutuhan dan konsep pernikahan Anda. Pemilihan vendor akan disesuaikan dengan ketersediaan, anggaran, serta kebutuhan acara yang telah dibicarakan bersama.',2,'active','2026-11-23 02:56:54','2026-11-23 02:56:54'),
('fa2b17f9-f0d4-4849-8373-8d787b80113e','Apakah saya bisa berkonsultasi terlebih dahulu sebelum memilih paket?','Perencanaan Pernikahan','Tentu. Anda dapat berkonsultasi dengan tim Sagita Wedding Planner untuk membicarakan konsep pernikahan, kebutuhan acara, jumlah tamu, dan anggaran yang telah disiapkan. Dari konsultasi tersebut, kami akan membantu memberikan gambaran layanan yang sesuai dengan kebutuhan Anda.',2,'active','2026-11-20 02:25:31','2026-11-23 02:46:23'),
('fd90f57c-53aa-4b5d-8e11-faea4808686d','Apa saja layanan yang ditawarkan oleh Sagita Wedding Planner?','Paket & Layanan','Sagita Wedding Planner menyediakan layanan Wedding Planner dan Wedding Organizer untuk membantu persiapan hingga pelaksanaan acara pernikahan. Cakupan layanan meliputi perencanaan, koordinasi vendor, penyusunan kebutuhan acara, dan koordinasi pada hari pernikahan sesuai dengan paket yang dipilih.',1,'active','2026-11-20 02:25:31','2026-11-23 02:48:03');
