INSERT INTO `order_workflow_settings` (`id`, `contract_template`, `checklist_template`, `updated_by`, `created_at`, `updated_at`) VALUES (1,'PERJANJIAN LAYANAN WEDDING ORGANIZER\nNomor dokumen: {{document_number}}\nTanggal diterbitkan: {{issued_at}}\n\nPenyedia layanan: Sagita Wedding Organizer\nPelanggan: {{customer_name}}\nNomor pesanan: {{order_number}}\n\nLayanan yang disepakati: {{package_name}} - {{option_name}}\nTanggal acara: {{event_date}}\nNilai pesanan: {{total_amount}}\nPembayaran terverifikasi: {{amount_paid}}\nSisa pembayaran: {{remaining_amount}}\n\nRincian layanan mengikuti paket dan layanan tambahan yang tercatat pada pesanan.\nPerubahan tanggal atau layanan harus diajukan melalui pesanan dan disetujui admin.\nKetentuan pembayaran dan pembatalan mengikuti kebijakan yang ditampilkan saat pemesanan.\n\nDokumen ini mencatat rincian pesanan dan belum menggantikan persetujuan/tanda tangan para pihak.','[{\"title\":\"Konfirmasi detail acara\",\"description\":\"Pastikan lokasi, waktu, dan kontak utama acara sudah benar.\",\"weeks_before_event\":16},{\"title\":\"Finalisasi jumlah tamu\",\"description\":\"Perbarui perkiraan jumlah tamu dan kebutuhan konsumsi.\",\"weeks_before_event\":12},{\"title\":\"Konfirmasi susunan acara\",\"description\":\"Tinjau susunan acara bersama tim wedding organizer.\",\"weeks_before_event\":8},{\"title\":\"Finalisasi kebutuhan vendor\",\"description\":\"Pastikan kebutuhan dekorasi, dokumentasi, dan vendor tambahan.\",\"weeks_before_event\":4},{\"title\":\"Konfirmasi akhir acara\",\"description\":\"Lakukan konfirmasi akhir detail dan jadwal acara.\",\"weeks_before_event\":1}]',NULL,'2026-11-22 06:32:36','2026-11-22 06:32:36');
