(2,'4a85c36a-caa6-4cc9-9ab6-47f77c0a9a67','Andrea',NULL,'6281380760095',NULL,NULL,NULL,'avatars/NVMVFyR5dLWAggqVdWc1fMVclwK346qZrgu14qMo.png','andrea@yogaroots.id','2026-09-10 19:18:50','$2y$12$VOU976RIB.YtryiO5x/FLOUT3t4Y1F.lj157lKfmsfniGJdEuTrYq',NULL,'2026-09-10 19:18:50','2026-09-10 19:20:27',NULL,NULL,NULL,NULL,'dsad','2026-09-11','P','Lainnya',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Andrea??????s yoga journey began as a personal quest to navigate life??????s everyday pressures in her career as a researcher. She has experienced firsthand how mindfulness can nurture inner peace and a more compassionate, purpose-driven life??????both on and off the mat.',NULL,NULL,NULL,NULL,NULL,NULL,'new_registered',NULL,'4 years',NULL),
(3,'57621d3c-c299-4cd2-b96a-9b887752cb73','Yogaroots.id',NULL,'85691333321',NULL,NULL,NULL,NULL,'tapayoga@yogaroots.id','2026-10-04 12:08:07','$2y$12$vgbZekTedJzp2ClDwMQrTOv4QFSMZuQBWukJ23jHyIwSfHx47jbNS',NULL,'2026-09-06 04:46:09','2026-10-04 12:08:07',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'new_registered',NULL,NULL,'sosmed'),
