(4,'70e15b9f-535a-42a2-8ea0-9a26ad7952e5','Wiku Pramesthi Bagaswara',NULL,'085691333321','jalan gandaria selatan',NULL,NULL,'avatars/r5YzPXmlkmO6PaSdbPUjr1dL5J9LoYUYVu5eWW9v.jpg','wikupb@gmail.com','2026-09-04 07:49:02','$2y$12$zXAvvf5TAYZg1O7CxzG6xOcUeWCEvbNLVndvd6Ja5ZD.ZN/.D3Bwu',NULL,'2025-11-12 03:39:36','2026-11-21 23:19:20','112161865449406232159',NULL,NULL,NULL,'Pati','1992-03-30','L','Islam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'new_registered',NULL,NULL,'website'),
(5,'755e0eaa-50e4-46db-9003-7c1fc6674876','Margaretta',NULL,NULL,NULL,NULL,NULL,'avatars/5qVq34VWSWBHYl4FgxzeSZqIEYRFotuSvA6qswLA.jpg','margaretta@yogaroots.id','2026-09-10 19:09:33','$2y$12$QxXHeDYBv0huosR6U1kUEe2Hq4uDAsdqJlo98wJhBbMiYRpAeZqKu',NULL,'2026-09-10 19:09:33','2026-09-10 19:21:22',NULL,NULL,NULL,NULL,'dasdas','2026-09-11','P','Lainnya',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'With a practice grounded in Hatha and Ashtanga, and refined through the precision of Iyengar alignment, Margaretta brings a thoughtful and therapeutic approach to teaching. Her work is especially focused on supporting the body through injury, recovery, and the transformative journey of pregnancy. She believes yoga is not about performance, but about creating a deeper relationship with the body, breath, and mind??????small practices that can quietly transform the way we move through everyday life. Beyond the mat, she continues to explore holistic approaches to wellbeing through Access Bars and Qi Gong.',NULL,NULL,NULL,NULL,NULL,NULL,'new_registered',NULL,'5 years',NULL),
(6,'787b72ea-59d0-4d54-848b-c200bddafdd2','super-admin',NULL,NULL,'Jl. Gandaria',4,17,'avatars/u5KMRU9jG95SYcdq0vhxnksQ0EFatee9WxrPxrtH.jpg','super@admin.com','2025-09-16 00:23:37','$2y$12$PRZJcd.nlREU6NRq3jvIVemYmlwxVPTb7En4URyNgyQSfKjWUzwDi','dpT7eK13sGv8C4yLn7gZZs3eMquEcHnwBUCwf3dMOw1F7GI9E0t1EEU5ROrD','2025-09-16 00:23:37','2026-09-06 23:43:32',NULL,NULL,NULL,NULL,'dasda','2025-09-24','P','Lainnya',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'sdsddsad',NULL,NULL,NULL,NULL,NULL,NULL,'new_registered',NULL,'10 tahun',NULL),
(7,'95294c43-b3d8-4b46-b938-e4eea1f3a359','Soni',NULL,'8534324202','sdcsddfs',NULL,NULL,'avatars/ImiYBm1Cjs7Sw0eCNBO1Dz6w5XDpNYBWnxoPy5Yc.jpg','soni@yogaroots.id','2026-09-03 18:34:37','$2y$12$jj/33jNGDxqzXGloYFeLMO5mozoP0v2atkzwf/S7ogXydL8n1hf4G',NULL,'2026-09-03 18:34:37','2026-09-06 23:44:15',NULL,NULL,NULL,NULL,'dasdas','2026-09-04','L','Kristen',NULL,'2026-09-03 17:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Soni is a certified RIMYI Introductory Level 2 yoga teacher with over 20 years of experience. His athletic background includes sepak takraw and college hockey, which inspired his path to becoming a sports teacher. His extensive experience allows him to skillfully guide and mentor his students, nurturing them into better practitioners. Join him on a transformative yoga journey, where his years of experience and unwavering dedication are at your service, helping you thrive as a yoga student',NULL,NULL,NULL,NULL,NULL,NULL,'new_registered',NULL,'20 years',NULL),
(14,'98285022-71b5-4120-b6c0-b3cc3670279c','QA Konsultasi',NULL,NULL,NULL,NULL,NULL,NULL,'qa.konsultasi@example.test','2026-11-20 07:06:36','$2y$12$IFLmMNANfUgTE..jGcqGh.f7849gC1Cc.gKTuug4vN9NzZY0voygq',NULL,'2026-11-20 07:06:36','2026-11-20 07:23:40',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-20 07:23:40',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'new_registered',NULL,NULL,NULL),
(8,'b497082d-dd9f-4d1c-a611-9e1331eb5393','Ophellia',NULL,'43242342',NULL,NULL,NULL,'avatars/76SUexkx0DwjJYj03iz6y3EBob9jrQWldE5I1GXU.jpg','ophellia@yogaroots.id','2026-09-10 19:24:15','$2y$12$EYxioqiLzM1FKBBE0XsTzeEX41St.5ocxnaLflhUHOHd0JMAY.yX.',NULL,'2026-09-10 19:24:15','2026-11-20 12:44:20',NULL,NULL,NULL,NULL,'dsad','2026-09-24','L','Lainnya',NULL,'2026-11-19 17:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Rooted in mindful movement and conscious alignment, her teaching invites students to cultivate greater awareness, presence, and ease in their practice. With over 800 hours of yoga education and teacher training, she has studied Yoga Fundamentals at Iyengar Yoga Institute Indonesia. Since April 2024, she has been part of the Yoga Roots teaching community, offering a grounded and attentive approach to every practice.',NULL,NULL,NULL,NULL,NULL,NULL,'new_registered',NULL,'4 years',NULL),
(9,'b55eb675-019c-4fa5-936e-579e2835527d','Yuniar',NULL,NULL,NULL,NULL,NULL,'avatars/XjtPl3c2Q5k9OB5ukHIJRmwX2o6vdiPX465T0uZy.jpg','yuniar@yogaroots.id','2026-09-10 19:07:05','$2y$12$10Z.D3afA7m8Dlt16WfINORNIOzHJadrDcJCx.RChxCnRvlm.oikO',NULL,'2026-09-10 19:07:05','2026-09-10 19:07:05',NULL,NULL,NULL,NULL,'dsad','2026-09-11','P','Islam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'With a practice rooted in Iyengar Yoga, Yuniar brings warmth, clarity, and a natural sense of ease to her teaching. She began practising and teaching in 2007, and since then has dedicated her practice to helping students feel at home on the mat. With a particular strength in alignment and beginner guidance, her classes offer a welcoming space to begin??????or begin again??????with curiosity and confidence. Her teaching is natural, friendly, and joyful, inviting each student to discover that yoga can be both precise and deeply personal.',NULL,NULL,NULL,NULL,NULL,NULL,'new_registered',NULL,'20 years',NULL),
(10,'beaaf326-874c-48c2-b6b8-6bbe655c4df2','Sita Manwani',NULL,NULL,NULL,NULL,NULL,'avatars/5xS7NpjOu3vPmgLh75j4rPpNSRWDr2JDAxYD2v1c.jpg','sita@yogaroots.id','2026-09-10 19:13:42','$2y$12$D7l1Tg6O9KnxTkHWNKOsouAYcxoTVuqDxqg3Zi9LDtFibOdlO1lw6',NULL,'2026-09-10 19:13:42','2026-09-10 23:58:20',NULL,NULL,NULL,NULL,'dasdas','2026-09-11','P','Lainnya',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Sita is a dedicated and certified yoga teacher with a journey that began at the Art of Living Foundation in 2006. There, she completed the Sri Sri Yoga Teachers Training Course and subsequently became an Art of Living teacher, where she learned how to teach Sudarshan Kriya breathwork. She holds accreditation from the Iyengar Yoga Institute and certifications from both the Sri Sri School of Yoga and the Indian Yoga Association. Her strong belief in yoga\'s potential to unlock the meditative mind\'s power and enhance life drives her passion. As the senior instructor at Yoga Roots, she leads the beginner yoga classes and the SKY breath work classes.\r\n\r\nSita has just completed 100hour Advanced Yoga Teacher Training including Traditional Chinese Medicine Principles, 5 Elements Theory, applied Meridian Sequences for Mandala Vinyasa System and Osteo - Thai Massage.',NULL,NULL,NULL,NULL,NULL,NULL,'new_registered',NULL,'10 years',NULL),
